 cols=[("Bestellung",14,None,"d",""),("Stammkunde",13,None,"d",""),("Warenwert",14,EURO,"d",""),("Versand",20,None,"f",'=IF(OR(B{r}="ja",C{r}>=100),"versandkostenfrei","Versandkosten")'),("Rabattsatz",12,PROZ,"f",'=IF(OR(B{r}="ja",C{r}>=300),0.05,0)')],
